arguments.command:
export OPAMROOT=/root/.opam; eval $(opam env --switch=compcert) 2>/dev/null; cd /tmp/CompCert; ./ccomp -v 2>&1 | head -2; cat > /tmp/hello.c <<'EOF'
#include <stdio.h>
int fib(int n){return n<2?n:fib(n-1)+fib(n-2);}
int main(){printf("hello %d\n", fib(10)); return 0;}
EOF
./ccomp -o /tmp/hello /tmp/hello.c 2>&1 | tail -5 && /tmp/hello && echo "EXIT=$?"

